from __future__ import annotations

from importlib import metadata
from typing import Dict, List, Optional


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """
    Map each provided distribution name (exactly as given) to the installed
    version string, or None if not installed.

    Matching is case-insensitive.
    """
    # Build a case-insensitive lookup of installed distributions.
    installed: dict[str, str] = {}
    for dist in metadata.distributions():
        try:
            dist_name = dist.metadata.get("Name")
        except Exception:
            # Be defensive: a broken metadata entry should not break reporting.
            continue
        if not dist_name:
            continue
        key = dist_name.casefold()
        # If duplicates exist, keep the first encountered; generally should not happen.
        installed.setdefault(key, dist.version)

    result: Dict[str, Optional[str]] = {}
    for requested in names:
        result[requested] = installed.get(requested.casefold())
    return result

