from __future__ import annotations

import re
from typing import Any


_EMAIL_RE = re.compile(
    # Simple, pragmatic email validator (sufficient for API input validation)
    r"^(?=.{1,254}$)(?P<local>[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+)@"
    r"(?P<domain>[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9]"
    r"(?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*)$"
)

_ALLOWED_PLANS = {"free", "pro", "team"}


class ValidationError(ValueError):
    """Validation error with per-field messages."""

    def __init__(self, messages: dict[str, list[str]]):
        super().__init__("Invalid sign-up data")
        self.messages = messages


def validate_signup(data: dict) -> dict:
    """
    Validate and clean sign-up endpoint payload.

    Required:
      - username: alphanumeric string
      - email: valid email address

    Optional:
      - plan: default "free", must be one of "free", "pro", "team"
      - age: integer, 16..120 inclusive

    Unknown keys are dropped.

    Returns:
      cleaned dict with default plan filled in.

    Raises:
      ValueError (with .messages attribute) on invalid input.
    """
    if not isinstance(data, dict):
        raise ValidationError({"data": ["Must be an object/dict."]})

    cleaned: dict[str, Any] = {}
    errors: dict[str, list[str]] = {}

    def add_error(field: str, msg: str) -> None:
        errors.setdefault(field, []).append(msg)

    # username (required)
    username = data.get("username", None)
    if username is None:
        add_error("username", "This field is required.")
    else:
        if not isinstance(username, str):
            add_error("username", "Must be a string.")
        else:
            if not username:
                add_error("username", "Must not be empty.")
            # Alphanumeric string only
            if not re.fullmatch(r"[A-Za-z0-9]+", username or ""):
                add_error("username", "Must contain only alphanumeric characters.")

    # email (required)
    email = data.get("email", None)
    if email is None:
        add_error("email", "This field is required.")
    else:
        if not isinstance(email, str):
            add_error("email", "Must be a string.")
        else:
            email_stripped = email.strip()
            if not _EMAIL_RE.match(email_stripped):
                add_error("email", "Must be a valid email address.")
            else:
                cleaned["email"] = email_stripped

    # plan (optional, default "free")
    plan = data.get("plan", "free")
    if plan is None:
        # If explicitly provided as None, treat as invalid.
        add_error("plan", 'Must be one of "free", "pro", "team".')
    else:
        if not isinstance(plan, str):
            add_error("plan", 'Must be one of "free", "pro", "team".')
        else:
            plan_stripped = plan.strip()
            if plan_stripped not in _ALLOWED_PLANS:
                add_error("plan", 'Must be one of "free", "pro", "team".')
            else:
                cleaned["plan"] = plan_stripped

    # age (optional)
    if "age" in data:
        age = data.get("age", None)
        if age is None:
            add_error("age", "Must be an integer between 16 and 120.")
        else:
            # Allow bool? In Python bool is subclass of int; usually not desired.
            if isinstance(age, bool) or not isinstance(age, int):
                add_error("age", "Must be an integer between 16 and 120.")
            else:
                if age < 16 or age > 120:
                    add_error("age", "Must be between 16 and 120 inclusive.")
                else:
                    cleaned["age"] = age

    # username cleaned if no errors for it
    if "username" not in errors and username is not None and isinstance(username, str):
        cleaned["username"] = username

    # Ensure default plan filled in even if not provided and no plan errors
    if "plan" not in cleaned and "plan" not in errors:
        cleaned["plan"] = "free"

    if errors:
        raise ValidationError(errors)

    # Drop unknown keys by only returning cleaned.
    return cleaned

from __future__ import annotations

from typing import TypedDict
import importlib.metadata


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """
    Map each provided distribution name (as given) to its installed version string,
    matching names case-insensitively, or None if not installed.

    Example:
        dependency_report(["HttpX", "missing"]) -> {"HttpX": "0.28.1", "missing": None}
    """
    # Build a lookup of installed distributions: lowercase name -> version
    installed: dict[str, str] = {}
    for dist in importlib.metadata.distributions():
        try:
            dist_name = dist.metadata.get("Name")
            if not dist_name:
                continue
            version = dist.version
            installed[dist_name.lower()] = version
        except Exception:
            # Be defensive: a single problematic dist shouldn't break reporting
            continue

    report: dict[str, str | None] = {}
    for requested in names:
        version = installed.get(requested.lower())
        report[requested] = version
    return report

