    r"(?i)^(?P<local>[a-z0-9.!#$%&'*+/=?^_`{|}~-]+)"
    r"@(?P<domain>[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*)$"
