def validate_signup(data: dict) -> dict:
    """
    Validate and clean sign-up payload.

    Required:
      - username: alphanumeric string
      - email: valid email address

    Optional:
      - plan: defaults to "free", must be one of {"free","pro","team"}
      - age: integer in [16, 120] inclusive

    Unknown keys are dropped.

    On invalid input, raise ValueError with a `messages` attribute:
      {field_name: [error_message, ...], ...}
    """
    if not isinstance(data, dict):
        err = ValueError("Invalid signup data")
        err.messages = {"data": ["Expected an object/dict."]}
        raise err

    cleaned: dict[str, Any] = {}
    messages: dict[str, list[str]] = {}

    # username
    username = data.get("username", None)
    if username is None:
        messages["username"] = ["This field is required."]
    elif isinstance(username, str):
        if not username:
            messages.setdefault("username", []).append("Username must not be empty.")
        elif not username.isalnum():
            messages.setdefault("username", []).append("Username must be alphanumeric.")
        else:
            cleaned["username"] = username
    else:
        messages.setdefault("username", []).append("Username must be a string.")

    # email
    email = data.get("email", None)
    if email is None:
        messages["email"] = ["This field is required."]
    elif isinstance(email, str):
        email = email.strip()
        if not email:
            messages.setdefault("email", []).append("Email must not be empty.")
        elif _EMAIL_RE.match(email) is None:
            messages.setdefault("email", []).append("Enter a valid email address.")
        else:
            cleaned["email"] = email
    else:
        messages.setdefault("email", []).append("Email must be a string.")

    # plan (optional, default free)
    plan = data.get("plan", "free")
    if plan is None:
        plan = "free"
    if isinstance(plan, str):
        plan = plan.strip()
        allowed = {"free", "pro", "team"}
        if plan not in allowed:
            messages.setdefault("plan", []).append('Plan must be one of: "free", "pro", "team".')
        else:
            cleaned["plan"] = plan
    else:
        messages.setdefault("plan", []).append('Plan must be one of: "free", "pro", "team".')

    # age (optional)
    if "age" in data and data.get("age") is not None:
        age = data.get("age")
        if isinstance(age, bool):
            # bool is a subclass of int; reject explicitly
            messages.setdefault("age", []).append("Age must be an integer between 16 and 120.")
        elif isinstance(age, int):
            if age < 16 or age > 120:
                messages.setdefault("age", []).append("Age must be between 16 and 120.")
            else:
                cleaned["age"] = age
        else:
            messages.setdefault("age", []).append("Age must be an integer between 16 and 120.")

    if messages:
        err = ValueError("Invalid signup data")
        err.messages = messages
        raise err

    return cleaned

