import re
from typing import Any


_USERNAME_RE = re.compile(r"^[A-Za-z0-9]+$")

# Simple, pragmatic email pattern suitable for input validation.
# (Not fully RFC-complete, but adequate for typical API sign-up flows.)
_EMAIL_RE = re.compile(
    r"^(?P<local>[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+)"
    r"@"
    r"(?P<domain>[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*)$"
)


class _SignupValidationError(ValueError):
    def __init__(self, messages: dict[str, list[str]]):
        super().__init__("Invalid sign-up data")
        self.messages = messages


def validate_signup(data: dict) -> dict:
    """
    Validate and clean sign-up endpoint input.

    Required:
      - username: alphanumeric string
      - email: valid e-mail address

    Optional:
      - plan: one of {"free","pro","team"} (default "free")
      - age: integer in [16, 120]

    Unknown keys are dropped.

    On invalid input, raises ValueError with a `messages` attribute:
      {field_name: [error_message, ...], ...}
    """
    if not isinstance(data, dict):
        raise _SignupValidationError({"_schema": ["Input must be a JSON object."]})

    errors: dict[str, list[str]] = {}
    cleaned: dict[str, Any] = {}

    # username
    username = data.get("username", None)
    if username is None:
        errors.setdefault("username", []).append("Missing data for required field.")
    elif not isinstance(username, str) or not _USERNAME_RE.fullmatch(username):
        errors.setdefault("username", []).append(
            "Must be an alphanumeric string containing only letters and digits."
        )
    else:
        cleaned["username"] = username

    # email
    email = data.get("email", None)
    if email is None:
        errors.setdefault("email", []).append("Missing data for required field.")
    elif not isinstance(email, str) or not _EMAIL_RE.fullmatch(email.strip()):
        errors.setdefault("email", []).append("Must be a valid e-mail address.")
    else:
        cleaned["email"] = email.strip()

    # plan (optional, default "free")
    plan = data.get("plan", "free")
    if plan is None:
        plan = "free"

    if isinstance(plan, str):
        plan_str = plan
    else:
        plan_str = None

    allowed_plans = {"free", "pro", "team"}
    if plan_str is None:
        errors.setdefault("plan", []).append("Must be one of: free, pro, team.")
    elif plan_str not in allowed_plans:
        errors.setdefault("plan", []).append("Must be one of: free, pro, team.")
    else:
        cleaned["plan"] = plan_str

    # age (optional)
    if "age" in data:
        age = data.get("age", None)
        if age is None:
            errors.setdefault("age", []).append("Age must be an integer between 16 and 120.")
        elif isinstance(age, bool) or not isinstance(age, int):
            errors.setdefault("age", []).append("Age must be an integer between 16 and 120.")
        elif age < 16 or age > 120:
            errors.setdefault("age", []).append("Age must be between 16 and 120 (inclusive).")
        else:
            cleaned["age"] = age

    if errors:
        raise _SignupValidationError(errors)

    return cleaned

