from __future__ import annotations

import re
from typing import Any


_EMAIL_RE = re.compile(
    # Pragmatic, non-RFC regex suitable for typical validations.
    r"^(?P<local>[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+)"
    r"@"
    r"(?P<domain>[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*)$"
)


class SignupValidationError(ValueError):
    """Validation error that exposes per-field messages via `messages`."""

    def __init__(self, messages: dict[str, list[str]]):
        super().__init__("Invalid sign-up data")
        self.messages = messages


def validate_signup(data: dict) -> dict:
    """
    Validate and clean sign-up payload.

    Required:
      - username: alphanumeric string
      - email: valid email address (basic validation)

    Optional:
      - plan: defaults to "free"; must be one of {"free", "pro", "team"}
      - age: integer in [16, 120] inclusive

    Unknown keys are dropped.

    Returns the cleaned dict with default plan filled in.

    Raises:
      - ValueError with a `messages` attribute mapping each invalid field
        name to a list of error messages.
    """
    if not isinstance(data, dict):
        raise SignupValidationError({"data": ["Expected an object/dict."]})

    allowed_keys = {"username", "email", "plan", "age"}
    cleaned: dict[str, Any] = {k: v for k, v in data.items() if k in allowed_keys}

    errors: dict[str, list[str]] = {}

    # username (required)
    username = cleaned.get("username", None)
    if username is None:
        errors.setdefault("username", []).append("Missing data for required field.")
    elif not isinstance(username, str):
        errors.setdefault("username", []).append("Must be a string.")
    elif not username:
        errors.setdefault("username", []).append("Must not be empty.")
    elif not username.isalnum():
        errors.setdefault("username", []).append("Must be alphanumeric.")

    # email (required)
    email = cleaned.get("email", None)
    if email is None:
        errors.setdefault("email", []).append("Missing data for required field.")
    elif not isinstance(email, str):
        errors.setdefault("email", []).append("Must be a string.")
    elif not _EMAIL_RE.match(email):
        errors.setdefault("email", []).append("Not a valid email address.")

    # plan (optional, default "free")
    plan = cleaned.get("plan", "free")
    if "plan" not in cleaned:
        cleaned["plan"] = "free"
    if plan is None:
        errors.setdefault("plan", []).append("Must be one of: free, pro, team.")
    elif not isinstance(plan, str):
        errors.setdefault("plan", []).append("Must be a string.")
    else:
        allowed_plans = {"free", "pro", "team"}
        if plan not in allowed_plans:
            errors.setdefault("plan", []).append("Must be one of: free, pro, team.")

    # age (optional)
    if "age" in cleaned:
        age = cleaned.get("age")
        if not isinstance(age, int) or isinstance(age, bool):
            errors.setdefault("age", []).append("Must be an integer.")
        else:
            if age < 16 or age > 120:
                errors.setdefault("age", []).append("Must be between 16 and 120 inclusive.")

    if errors:
        raise SignupValidationError(errors)

    return cleaned
